def firstCompleteIndex(arr, mat):
    m, n = len(mat), len(mat[0])

    # Map value to its (row, col) position
    pos = {}
    for i in range(m):
        for j in range(n):
            pos[mat[i][j]] = (i, j)

    # Track counts for each row and each column
    row_count = [0] * m
    col_count = [0] * n

    for i, v in enumerate(arr):
        r, c = pos[v]
        row_count[r] += 1
        if row_count[r] == n:
            return i
        col_count[c] += 1
        if col_count[c] == m:
            return i
    return -1
